// Derive the learner-facing examples from the reviewed numerical fixture.
// Run with --check in CI; regenerate after an intentional fixture change.
import fs from 'node:fs';
import assert from 'node:assert/strict';
const ids = [
  'book-mechanics-p32-r03', 'book-mechanics-p32-r04', 'book-mechanics-p32-r05',
  'book-mechanics-p32-r09', 'book-mechanics-p32-r10', 'book-mechanics-p32-r11',
  'book-mechanics-p33-r01', 'book-mechanics-p33-r02', 'book-mechanics-p33-r03', 'book-mechanics-p33-r05',
];
const {cases} = JSON.parse(fs.readFileSync('tests/fixtures/students-worked-cases-20261027.json', 'utf8'));
const selected = ids.map(id => {
  const matches = cases.filter(c => c.id === id);
  assert.equal(matches.length, 1, 'One unambiguous learner example required: ' + id);
  assert.equal(matches[0].side, 1);
  assert.equal(matches[0].degrees, false);
  return matches[0];
});
const output = `/* Generated by tests/students-worked-examples-data-20261027.mjs. Do not edit directly. */
(function(){
'use strict';
const study=window.MT_STUDY;
const cases=${JSON.stringify(selected, null, 2)};
study.workedExamples=Object.fromEntries(cases.map(c=>[c.id,c]));
for(const r of study.sourceEquationRegister){
 if(study.workedExamples[r.id]){
  r.numericStatus='REFERENCE_CASE_COVERED';
  r.workedCaseTestReference='tests/students-worked-cases-20261027.mjs';
 }
}
})();
`;
const target = 'students/worked-examples-20261027.js';
if(process.argv.includes('--check')) assert.equal(fs.readFileSync(target,'utf8').replace(/\r\n/g,'\n'),output,'Regenerate learner examples from the reviewed fixture');
else fs.writeFileSync(target,output);
console.log(JSON.stringify({status:'PASS',examples:selected.length,generated:!process.argv.includes('--check')}));
